class Solution {
public:
    int conv(const string& d) {
        int months[] = {31,28,31,30,31,30,31,31,30,31,30,31};
        int m = stoi(d.substr(0,2)), dd = stoi(d.substr(3));
        int res = dd;
        for (int i = 0; i < m-1; i++) res += months[i];
        return res;
    }
    int countDaysTogether(string aA, string lA, string aB, string lB) {
        return max(0, min(conv(lA), conv(lB)) - max(conv(aA), conv(aB)) + 1);
    }
};

