class Solution {
    private int conv(String d) {
        int[] months = {31,28,31,30,31,30,31,31,30,31,30,31};
        int m = Integer.parseInt(d.substring(0,2)), dd = Integer.parseInt(d.substring(3));
        int res = dd;
        for (int i = 0; i < m-1; i++) res += months[i];
        return res;
    }
    public int countDaysTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        return Math.max(0, Math.min(conv(leaveAlice), conv(leaveBob)) - Math.max(conv(arriveAlice), conv(arriveBob)) + 1);
    }
}

