var countDaysTogether = function(aA, lA, aB, lB) {
    const months = [31,28,31,30,31,30,31,31,30,31,30,31];
    const conv = d => {
        const m = +d.slice(0,2), dd = +d.slice(3);
        let res = dd;
        for (let i = 0; i < m-1; i++) res += months[i];
        return res;
    };
    return Math.max(0, Math.min(conv(lA), conv(lB)) - Math.max(conv(aA), conv(aB)) + 1);
};
